import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { fetchMachinesForCurrentUser, fetchTmForCurrentUser, fetchClaimsForCurrentUser } from '../services/api';
import NewMachineCreate from '../components/NewMachineCreate';
import NewTmCreate from '../components/NewTmCreate';
import NewClaimCreate from '../components/NewClaimCreate';

export default function DashboardPage() {

  const navigate = useNavigate();
  const { user } = useAuth();
  const [loading, setLoading] = useState(false);
  const [notFound, setNotFound] = useState(false);
  const [activeTab, setActiveTab] = useState('info');
  const [showNewMachine, setShowNewMachine] = useState(false);
  const [showNewTm, setShowNewTM] = useState(false);
  const [showNewClaim, setShowNewClaim] = useState(false);
  const [machines, setMachines] = useState([]);
  const [tm, setTm] = useState([]);
  const [claims, setClaims] = useState([]);
  const [filters, setFilters] = useState({ 
    model_machine: '',
    model_engine: '',
    model_transmission: '',
    model_controlled_bridge: '',
    model_driving_bridge: '',
    serial_number_machine: '',
    type_of_tm: '',
    service_company: '',
    component_failure: '',
    recovery_method: ''
  });

    const isManager = useMemo(() => {
  if (!user) return false;

  // 1) groups может быть массивом строк
  const groups = user.groups ?? [];
  if (Array.isArray(groups) && groups.length) {
    if (typeof groups[0] === 'string') {
      return groups.includes('Manager');
    }
    // 2) groups может быть массивом объектов: [{ name: 'Manager' }, ...]
    if (typeof groups[0] === 'object') {
      return groups.some((g) => (g.name ?? '') === 'Manager');
    }
  }

  // 3) альтернативы, если есть другие поля
  if (typeof user.group === 'string') {
    return user.group === 'Manager';
  }
  if (typeof user.role === 'string') {
    return user.role === 'Manager';
  }

  // 4) дополнительный флаг, если он появится
  if (typeof user.is_manager === 'boolean') {
    return user.is_manager;
  }

  return false;
}, [user]);

  const isService = useMemo(() => {
    if (!user) return false;


  const groups = user.groups ?? [];
  if (Array.isArray(groups) && groups.length) {
    if (typeof groups[0] === 'string') {
      return groups.includes('ServiceCompany');
    }

    if (typeof groups[0] === 'object') {
      return groups.some((g) => (g.name ?? '') === 'ServiceCompany');
    }
  }

  if (typeof user.group === 'string') {
    return user.group === 'ServiceCompany';
  }
  if (typeof user.role === 'string') {
    return user.role === 'ServiceCompany';
  }

  // 4) дополнительный флаг, если он появится
  if (typeof user.is_service_company === 'boolean') {
    return user.is_service_company;
  }

  return false;
}, [user]);

  const handleCreated = (newMachine) => {
    setShowNewMachine(false);
    //loadMachines();
  };

   const handleCreatedTm = (newTm) => {
    setShowNewTM(false);
  }; 

    const handleCreatedClaim = (newClaim) => {
    setShowNewClaim(false);
  }; 


  const getDisplayValue = (m, key) => { 
    const v = m?.[key]; 
    if (v && typeof v === 'object') { return v.name ?? v.id ?? ''; } 
    return v ?? ''; 
};

  // Имя пользователя для отображения
  const userName =
    user?.username ||
    user?.name ||
    user?.first_name ||
    user?.customer?.name ||
    user?.service_company?.name ||
    'Пользователь';

  // Загрузка данных машин при переходе во вкладку "Общая информация"
  useEffect(() => {
    if (activeTab !== 'info') return;

    // Сортировка по умолчанию - по date_tm (возрастание)
    // const [sortKey, setSortKey] = useState('date_shipment_from_factory');
    // const [sortAsc, setSortAsc] = useState(true);

    const loadMachines = async () => {
      try {
        const data = await fetchMachinesForCurrentUser();
        setMachines(Array.isArray(data) ? data : []);
      } catch {
        setNotFound(true);
      } finally {
        setLoading(false);
      }
    };

    setLoading(true);
    loadMachines();
  }, [activeTab]);

    // Загрузка данных машин при переходе во вкладку "ТО"
  useEffect(() => {
    if (activeTab !== 'TO') return;
        // Сортировка по умолчанию - по date_tm(возрастание)
    // const [sortKey, setSortKey] = useState('date_tm');
    // const [sortAsc, setSortAsc] = useState(true);

    const loadTM = async () => {
      try {
        const data = await fetchTmForCurrentUser();
        setTm(Array.isArray(data) ? data : []);
      } catch {
        setNotFound(true);
      } finally {
        setLoading(false);
      }
    };

    setLoading(true);
    loadTM();
  }, [activeTab]);

     // Загрузка данных машин при переходе во вкладку "Рекламации"
  useEffect(() => {
    if (activeTab !== 'Рекламации') return;
        // Сортировка по умолчанию - по date_failure(возрастание)
    // const [sortKey, setSortKey] = useState('date_failure');
    // const [sortAsc, setSortAsc] = useState(true);

    const loadClaims = async () => {
      try {
        const data = await fetchClaimsForCurrentUser();
        setClaims(Array.isArray(data) ? data : []);
      } catch {
        setNotFound(true);
      } finally {
        setLoading(false);
      }
    };

    setLoading(true);
    loadClaims();
  }, [activeTab]);

  // Фильтрация 
  const filteredMachines = useMemo(() => { 
    return machines.filter((m) => { 
        const mm = String(getDisplayValue(m, 'model_machine')).toLowerCase();
        const me = String(getDisplayValue(m, 'model_engine')).toLowerCase();
        const tr = String(getDisplayValue(m, 'model_transmission')).toLowerCase();
        const cb = String(getDisplayValue(m, 'model_controlled_bridge')).toLowerCase();
        const db = String(getDisplayValue(m, 'model_driving_bridge')).toLowerCase(); 
        const sn = String(m?.serial_number_machine ?? '').toLowerCase();
        const f1 = filters.model_machine ? mm.includes(filters.model_machine.toLowerCase()) : true;
        const f2 = filters.model_engine ? me.includes(filters.model_engine.toLowerCase()) : true;
        const f3 = filters.model_transmission ? tr.includes(filters.model_transmission.toLowerCase()) : true;
        const f4 = filters.model_controlled_bridge ? cb.includes(filters.model_controlled_bridge.toLowerCase()) : true;
        const f5 = filters.model_driving_bridge ? db.includes(filters.model_driving_bridge.toLowerCase()) : true;
        const f6 = filters.serial_number_machine ? sn.includes(filters.serial_number_machine.toLowerCase()) : true;

        return f1 && f2 && f3 && f4 && f5 && f6;
    });
  }, [machines, filters]);

  const filteredClaims = useMemo(() => { 
    return claims.filter((m) => { 
        const cf = String(getDisplayValue(m, 'component_failure')).toLowerCase();
        const sc = String(getDisplayValue(m, 'service_company')).toLowerCase(); 
        const sn = String(m?.serial_number_machine ?? '').toLowerCase();
        const mr = String(getDisplayValue(m, 'recovery_method')).toLowerCase(); 
        const f1 = filters.component_failure? cf.includes(filters.component_failure.toLowerCase()) : true;
        const f2 = filters.service_company ? sc.includes(filters.service_company.toLowerCase()) : true;
        const f3 = filters.serial_number_machine ? sn.includes(filters.serial_number_machine.toLowerCase()) : true;
        const f4 = filters.recovery_method? mr.includes(filters.recovery_method.toLowerCase()) : true;

        return f1 && f2 && f3 && f4;
    });
  }, [claims, filters]);

    const filteredTm = useMemo(() => { 
    return tm.filter((m) => { 
        const tm = String(getDisplayValue(m, 'type_of_tm')).toLowerCase();
        const sc = String(getDisplayValue(m, 'service_company')).toLowerCase(); 
        const sn = String(m?.serial_number_machine ?? '').toLowerCase();
        const f1 = filters.type_of_tm ? tm.includes(filters.type_of_tm.toLowerCase()) : true;
        const f2 = filters.service_company ? sc.includes(filters.service_company.toLowerCase()) : true;
        const f3 = filters.serial_number_machine ? sn.includes(filters.serial_number_machine.toLowerCase()) : true;

        return f1 && f2 && f3;
    });
  }, [tm, filters]);
const handleRowClick = (machine) => { 
    if (!machine?.id) return; navigate(`/machines/${machine.id}`); 
};

const handleRowClickTm = (tm) => { 
    if (!tm?.id) return; navigate(`/tm/${tm.id}`); 
};

const handleRowClickClaim = (claim) => { 
    if (!claim?.id) return; navigate(`/claims/${claim.id}`); 
};

const handleFilterChange = (e) => { 
    const { name, value } = e.target; setFilters((f) => ({ ...f, [name]: value })); 
};

  return (
    <div className="dashboard-page" style={{ padding: 16 }}>
      <div className="page-header" style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
        <h2>Панель управления</h2>
      </div>

      <div className="user-name" style={{ marginTop: 8, marginBottom: 16 }}>
        Вы вошли как: {userName}
      </div>

      <div className="dashboard-tabs" style={{ display: 'flex', gap: 8, marginBottom: 12 }}>
        <button onClick={() => setActiveTab('info')} className={activeTab === 'info' ? 'active' : ''}>
          Общая информация
        </button>
        <button onClick={() => setActiveTab('TO')} className={activeTab === 'TO' ? 'active' : ''}>
          ТО
        </button>
        <button onClick={() => setActiveTab('claims')} className={activeTab === 'claims' ? 'active' : ''}>
          Рекламации
        </button>
      </div>

      {loading && <div>Загрузка...</div>}

      {!loading && notFound && (
        <div>Не удалось загрузить данные машин.</div>
      )}
      
      {isManager && (
        <div style={{ margin: '12px 0' }}>
          <button onClick={() => setShowNewMachine((s) => !s)}>
            {showNewMachine ? 'Свернуть' : 'Создать новую машину'}
          </button>
        </div>
      )}

      {showNewMachine && (
        <NewMachineCreate onCreated={handleCreated} onCancel={() => setShowNewMachine(false)} />
      )}

      {isManager || isService && (
        <div style={{ margin: '12px 0' }}>
          <button onClick={() => setShowNewTM((s) => !s)}>
            {showNewTm ? 'Свернуть' : 'Создать новое ТО'}
          </button>
          <button onClick={() => setShowNewClaim((s) => !s)}>
            {showNewClaim ? 'Свернуть' : 'Создать новую Рекламацию'}
          </button>
        </div>
      )}

      {showNewTm && (
        <NewTmCreate onCreated={handleCreatedTm} onCancel={() => setShowNewTM(false)} />
      )}

      {showNewClaim && (
        <NewClaimCreate onCreated={handleCreatedClaim} onCancel={() => setShowNewClaim(false)} />
      )}


      {!loading && !notFound && activeTab === 'info' && (
        <div>
            <div className="filters" style={{ display: 'flex', gap: 8, margin: '8px 0 12px 0' }}>
                <input
                placeholder="Машина"
                name="model_machine"
                value={filters.model_machine}
                onChange={handleFilterChange}
                />
                <input
                placeholder="Двигатель"
                name="model_engine"
                value={filters.model_engine}
                onChange={handleFilterChange}
                />
                <input
                placeholder="Трансмиссия"
                name="model_transmission"
                value={filters.model_transmission}
                onChange={handleFilterChange}
                />
                <input
                placeholder="Упр.мост"
                name="model_controlled_bridge"
                value={filters.model_controlled_bridge}
                onChange={handleFilterChange}
                />
                <input
                placeholder="Вед.мост"
                name="model_driving_bridge"
                value={filters.model_driving_bridge}
                onChange={handleFilterChange}
                />
                <input
                placeholder="SN машины"
                name="serial_number_machine"
                value={filters.serial_number_machine}
                onChange={handleFilterChange}
                />
            </div> 
          {machines.length === 0 ? (
            <div>Нет машин для отображения.</div>
          ) 
          : 
          (
            <table border="1" cellPadding="6" cellSpacing="0">
              <thead>
                <tr>
                  <th>Дата отгрузки</th>
                  <th>Модель машины</th>
                  <th>Серийный номер машины</th>
                  <th>Модель двигателя</th>
                  <th>Модель трансмиссии</th>
                  <th>Модель упр.моста</th>
                  <th>Модель ведущего моста</th>
                </tr>
              </thead>
              <tbody>
                {machines.map((m) => (
                  <tr key={m.id} 
                  onClick={() => handleRowClick(m)} 
                  style={{ cursor: 'pointer' }} 
                  role="button" 
                  tabIndex={0} 
                  onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { handleRowClick(m); } }} 
                  aria-label={`Перейти к данным машины ${m.serial_number_machine ?? ''}`} > 
                    
                    <td>
                        {m.date_shipment_from_factory}
                    </td>
                    <td>
                      {m.model_machine
                        ? typeof m.model_machine === 'object'
                          ? (m.model_machine.name || m.model_machine.id || '')
                          : m.model_machine
                        : ''}
                    </td>
                    <td>
                        {m.serial_number_machine ?? ''}
                    </td>        
                    <td>
                      {m.model_engine
                        ? typeof m.model_engine === 'object'
                          ? (m.model_engine.name || m.model_engine.id || '')
                          : m.model_engine
                        : ''}
                    </td>
                    <td>
                      {m.model_transmission
                        ? typeof m.model_transmission === 'object'
                          ? (m.model_transmission.name || m.model_transmission.id || '')
                          : m.model_transmission
                        : ''}
                    </td>
                    <td>
                      {m.model_controlled_bridge
                        ? typeof m.model_controlled_bridge === 'object'
                          ? (m.model_controlled_bridge.name || m.model_controlled_bridge.id || '')
                          : m.model_controlled_bridge
                        : ''}
                    </td>
                    <td>
                      {m.model_driving_bridge
                        ? typeof m.model_driving_bridge === 'object'
                          ? (m.model_driving_bridge.name || m.model_driving_bridge.id || '')
                          : m.model_driving_bridge
                        : ''}
                    </td>
                    
                  </tr>
                ))}
              </tbody>
            </table>
            )
          }
        </div>
      )
    }
    {!loading && !notFound && activeTab === 'TO' && (
        <div>
            <div className="filters" style={{ display: 'flex', gap: 8, margin: '8px 0 12px 0' }}>
                <input
                placeholder="Вид ТО"
                name="type_of_tm"
                value={filters.type_of_tm}
                onChange={handleFilterChange}
                />
                <input
                placeholder="Сервисная компания"
                name="service_company"
                value={filters.service_company}
                onChange={handleFilterChange}
                />
                <input
                placeholder="SN машины"
                name="serial_number_machine"
                value={filters.serial_number_machine}
                onChange={handleFilterChange}
                />
            </div> 
          {tm.length === 0 ? (
            <div>Нет ТО для отображения.</div>
          ) 
          : 
          (
            <table border="1" cellPadding="6" cellSpacing="0">
              <thead>
                <tr>
                  <th>Дата проведения ТО</th>
                  <th>Модель машины</th>
                  <th>Серийный номер машины</th>
                  <th>Вид ТО</th>
                  <th>Сервисная компания</th>
                  <th>Компания проводившая ТО</th>
                  
                </tr>
              </thead>
              <tbody>
                {tm.map((m) => (
                  <tr key={m.id} 
                  onClick={() => handleRowClickTm(m)} 
                  style={{ cursor: 'pointer' }} 
                  role="button" 
                  tabIndex={0} 
                  onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { handleRowClickTm(m); } }} 
                  aria-label={`Перейти к данным ТО ${m.id ?? ''}`} > 
                    
                    <td>
                        {m.date_tm}
                    </td>
                    <td>
                      {m.model_machine
                        ? typeof m.model_machine === 'object'
                          ? (m.model_machine.name || m.model_machine.id || '')
                          : m.model_machine
                        : ''}
                    </td>
                    <td>
                        {m.serial_number_machine ?? ''}
                    </td>        
                    <td>
                      {m.type_of_tm
                        ? typeof m.type_of_tm === 'object'
                          ? (m.type_of_tm.name || m.type_of_tm.id || '')
                          : m.type_of_tm
                        : ''}
                    </td>
                    <td>
                      {m.service_company
                        ? typeof m.service_company === 'object'
                          ? (m.service_company.name || m.service_company.id || '')
                          : m.service_company
                        : ''}
                    </td>
                    <td>
                      {m.tm_company
                        ? typeof m.tm_company === 'object'
                          ? (m.tm_company.name || m.tm_company.id || '')
                          : m.tm_company
                        : ''}
                    </td>
                   
                  </tr>
                ))}
              </tbody>
            </table>
            )
          }
        </div>
    )
    }
    {!loading && !notFound && activeTab === 'Рекламации' && (
            <div>
                <div className="filters" style={{ display: 'flex', gap: 8, margin: '8px 0 12px 0' }}>
                    <input
                    placeholder="Узел отказа"
                    name="component_failure"
                    value={filters.component_failure}
                    onChange={handleFilterChange}
                    />
                    <input
                    placeholder="Сервисная компания"
                    name="service_company"
                    value={filters.service_company}
                    onChange={handleFilterChange}
                    />
                    <input
                    placeholder="SN машины"
                    name="serial_number_machine"
                    value={filters.serial_number_machine}
                    onChange={handleFilterChange}
                    />
                    <input
                    placeholder="Способ восстановления"
                    name="recovery_method"
                    value={filters.recovery_method}
                    onChange={handleFilterChange}
                    />
                </div>
            {claims.length === 0 ? (
                <div>Нет Рекламаций для отображения.</div>
          ) 
          : 
          (
            <table border="1" cellPadding="6" cellSpacing="0">
              <thead>
                <tr>
                  <th>Дата отказа</th>
                  <th>Модель машины</th>
                  <th>Серийный номер машины</th>
                  <th>Узел отказа</th>
                  <th>Сервисная компания</th>
                  <th>Способ восстановления</th>
                </tr>
              </thead>
              <tbody>
                {claims.map((m) => (
                  <tr key={m.id} 
                  onClick={() => handleRowClickClaim(m)} 
                  style={{ cursor: 'pointer' }} 
                  role="button" 
                  tabIndex={0} 
                  onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { handleRowClickClaim(m); } }} 
                  aria-label={`Перейти к данным Рекламации ${m.id ?? ''}`} > 
                    
                    <td>
                        {m.date_failure}
                    </td>
                    <td>
                      {m.model_machine
                        ? typeof m.model_machine === 'object'
                          ? (m.model_machine.name || m.model_machine.id || '')
                          : m.model_machine
                        : ''}
                    </td>
                    <td>
                        {m.serial_number_machine ?? ''}
                    </td>        
                    <td>
                      {m.component_failure
                        ? typeof m.component_failure === 'object'
                          ? (m.component_failure || m.component_failure.id || '')
                          : m.component_failure
                        : ''}
                    </td>
                    <td>
                      {m.recovery_method
                        ? typeof m.recovery_method === 'object'
                          ? (m.recovery_method.name || m.recovery_method.id || '')
                          : m.recovery_method
                        : ''}
                    </td>
                  </tr>
                ))}
                </tbody>
            </table>
          )
        }
        </div>
    )}
    </div>
)}
